// Skip PDF fetch: pass articles through without downloading
const articles = $('Input').all().map(i => i.json);
console.log('PDF Fetch SKIPPED: ' + articles.length + ' articles passed through without PDF download');
// Meme garde que dans la recuperation : ne jamais effacer un PDF deja fourni a l'import.
return articles.map(a => ({ json: { ...a,
  pdf_url: a.pdf_local ? (a.pdf_url || null) : null,
  pdf_local: a.pdf_local || null,
  pdf_source: a.pdf_local ? (a.pdf_source || 'import') : null,
  is_oa: a.pdf_local ? !!a.is_oa : false,
  oa_status: a.pdf_local ? 'already_local' : 'pdf_fetch_skipped' } }));

// === PDF FETCH v5 - Telechargement reel des PDFs (CASCADE_PDF_v5, 2026-10-16) ===
// UN FICHIER PAR ARTICLE (NOM_PDF_UNIQUE_v1, 2026-10-16 ; defaut P1 de la refutation du tour 4 du
// lot « chaine PDF », preexistant). Le PDF etait nomme `sanitizeFilename(article.title) + '.pdf'`, et
// les indices passes a la bibliotheque de references et a l'editeur souscrit valaient
// `title || doi` : un article sans titre devenait « article.pdf », deux titres egaux sur leurs 80
// premiers caracteres assainis (« Editorial ») tombaient sur le meme fichier ; le second
// telechargement remplacait le PDF du premier, les deux articles pointaient ce fichier, et le tri
// sur texte integral comme l'extraction lisaient le texte d'un autre article sans rien signaler. Un
// PDF deja la d'un run precedent devenait aussi la cible d'un article homonyme. DESORMAIS le nom est
// celui de `nomDuPdf` : 60 caracteres du titre assaini, « _ » et l'empreinte du DOI (FNV-1a sur 32
// bits, DOI en minuscules : le meme article garde son nom d'un run a l'autre), le meme pour les
// trois ecritures (relais /download, bibliotheque de references, editeur souscrit). La garde du run
// (`nomsPris`) leve une collision d'empreinte et protege les PDF deja la des autres articles. Le nom
// tient en 73 caracteres au plus ; l'ancien en tenait 80. Seul le nom des NOUVEAUX fichiers change :
// un PDF deja range garde son chemin (`pdf_local`), que tout l'aval lit.
// Sources, dans l'ordre : 0) la bibliotheque de references, 1) Unpaywall, 2) CORE, 3) Europe PMC
// (libre acces, telecharges par le relais /download), 4) l'editeur souscrit (route du moteur).
//
// LA CASCADE A PLUSIEURS CHANCES (2026-10-13, lot « chaine PDF »). CE QUI ETAIT FAUX, lu au HEAD
// 780e20c : des qu'une source libre donnait une adresse, les suivantes n'etaient plus essayees,
// l'editeur souscrit compris (condition « ni adresse ni fichier »), MEME SI LE TELECHARGEMENT
// ECHOUAIT ; une seule adresse d'Unpaywall etait tentee ; et l'article sans PDF ne disait rien
// d'autre que « pas de PDF ». DESORMAIS un telechargement refuse fait passer a l'adresse suivante :
// les autres adresses libres d'Unpaywall, puis CORE, puis Europe PMC, puis l'editeur souscrit.
// LA BORNE, PAR ARTICLE : ESSAIS_UNPAYWALL_MAX adresses d'Unpaywall (2), une de CORE, une
// d'Europe PMC, soit 4 telechargements au plus, une adresse deja essayee n'etant pas reprise ; puis
// une demande a l'editeur. LA DUREE D'UN ESSAI, telle que les delais de ce noeud la bornent :
// telechargement DELAI_TELECHARGEMENT_MS (75 s ; le relais rend sa reponse au plus 71 s apres
// l'arrivee de la demande, quelle que soit la phase ou le site traine : src/proxy.py, « LA
// DUREE », tour 3 du 2026-10-14) ; recherche Unpaywall 20 s, CORE DELAI_CORE_MS (60 s : le relais
// y espace les appels, 5 par 10 s, et fait l'attente d'un 429 jusqu'a 30 s), Europe PMC 15 s ;
// editeur DELAI_EDITEUR_MS (180 s, 2026-10-14 : la route tient en DUREE_MAX_ROUTE_S, 150 s, si
// chaque demande a l'editeur aboutit dans son delai, src/publisher_fetch.py). Ces bornes n'ont pas
// ete mesurees sur un vrai run.
// LE SIGNE DE VIE, A CHAQUE ARTICLE (PROGRESS_PDF_TICK_v2, 2026-10-14, tour 3). L'ecran
// (app/src/lib/api.ts, `runAndWait`), le planificateur (src/pipeline.py, `_run_module_step`) et la
// reprise (src/run_resume.py, `_worker`) abandonnent un run apres 20 min sans changement de la
// position publiee (/api/module-progress/tick). Ce noeud ne la publiait qu'un article sur trois ;
// avec les delais ci-dessus, un article peut durer 697,2 s (bibliotheque 120, Unpaywall 20, quatre
// telechargements de 75, CORE 60, Europe PMC 15, editeur 180, la position 2 et la pause 0,2), et
// trois articles plus de 20 min. La position part donc a chaque article. Le plus long silence que
// ces delais permettent (sept articles, chaque appel durant tout son delai ; sonde du tour 3 et
// tests/test_chaine_pdf_cascade.py) : 730,2 s, le premier, qui compte aussi l'ouverture
// de l'avancement et le bilan de la bibliotheque (33 s) ; 2 120,6 s un article sur trois.
// CHAQUE ESSAI RATE LAISSE SON MOTIF (`_pdf_essais`, « source:motif » dans l'ordre), et l'article
// sans PDF porte la cause du DERNIER essai pertinent (`_pdf_motif`, `_pdf_motif_fr`,
// `_pdf_motif_en`) et, depuis le 2026-10-14, le detail technique de cet essai quand il en a un
// (`_pdf_detail` : statut HTTP, texte d'une panne ou d'un refus de certificat).
// « PERTINENT » : un essai qui a eu lieu, c'est-a-dire une demande partie. La route de l'editeur
// le dit elle-meme (`demande_envoyee` faux, 2026-10-14) ; releve le meme jour dans
// src/publisher_fetch.py, elle le rend faux dans quatre cas : aucun DOI, editeur non gere, aucun
// acces enregistre, tour de cadence au-dela de l'attente permise. Une telle reponse n'est pas un
// essai. Sans essai rate, la cause est cette reponse de l'editeur, sauf l'editeur non gere, sinon
// `aucune_adresse_libre`.
// LES CHAMPS DE CAUSE D'UN RUN PRECEDENT (CHAMPS_DE_CAUSE) sont retires de chaque article, exclu
// compris, avant tout essai (2026-10-14) : la reprise d'un run renvoie les articles entiers
// (src/run_resume.py, `_worker`), et le rapport du module comptait la cause d'un run d'avant.
// « LIBRE ACCES » PAR PROVENANCE (meme date) : `is_oa` vaut vrai pour un PDF venu d'une source
// libre, faux pour un PDF de la bibliotheque de references ou de l'editeur souscrit ; sans PDF, il
// garde ce qu'Unpaywall dit de l'article. Depuis le tour 4 (2026-10-14), le PDF de la voie d'un
// editeur qui ne sert que son libre acces (EDITEURS_DU_LIBRE_ACCES) est en libre acces.

const PROXY = 'http://host.docker.internal:3456';
const ESSAIS_UNPAYWALL_MAX = 2;
const DELAI_TELECHARGEMENT_MS = 75000;
const DELAI_CORE_MS = 60000;
const DELAI_EDITEUR_MS = 180000;
const STATUTS_LIBRES = ['gold', 'green', 'hybrid', 'bronze', 'diamond'];
let EMAIL = 'ultralab-review@systematic-review.org';
try {
  const __cfg = await this.helpers.httpRequest({ method: 'GET', url: 'http://host.docker.internal:8080/api/config', timeout: 4000, json: true });
  // LA CONFIGURATION EST A PLAT (2026-10-14, tour 3) : GET /api/config la rend telle quelle
  // (src/server.py, `api_config`), et la rendait deja ainsi au commit d8ba2ad qui a pose cette
  // lecture (git show du 2026-10-14). Lue sous une clef `config`, qui n'existe pas, l'adresse
  // saisie dans les reglages n'etait jamais envoyee.
  const __e = __cfg && __cfg.unpaywall_email;
  if (__e && String(__e).indexOf('@') > 0) EMAIL = String(__e).trim();
} catch (e) {}
const items = $input.all();

if (!items || items.length === 0) {
  return [{ json: { error: 'no_input' } }];
}

const allArticles = items.map(i => i.json);
const outputFolder = (allArticles[0] && allArticles[0].output_folder) || '/desktop/review ultralab';
const pdfFolder = outputFolder + '\\pdfs';

const toFetch = allArticles.filter(a => a.screening_decision === 'Include' || a.screening_decision === 'Maybe');
const excluded = allArticles.filter(a => a.screening_decision === 'Exclude');

console.log('Recuperation des PDF : ' + toFetch.length + ' article(s) a traiter, ' + excluded.length + ' exclu(s)');
console.log('        (en) PDF retrieval: ' + toFetch.length + ' article(s) to process, ' + excluded.length + ' excluded');
console.log('Dossier des PDF : ' + pdfFolder);
console.log('        (en) PDF folder: ' + pdfFolder);

let stats = { unpaywall: 0, core: 0, downloaded: 0, failed: 0, no_doi: 0, sans_adresse: 0,
              telechargements_refuses: 0, motifs_pdf: {}, essais_pdf: {}, details_pdf: {},
              motifs_biblio: {}, replis_biblio: {}, sources_biblio: {}, avis_biblio: {}, details_biblio: {}, essais_biblio: {} };
// Les libelles des motifs viennent du moteur (francais et anglais) : le nœud ne tient aucune
// table a lui, deux copies d'une liste fermee finissent toujours par diverger. UNE SEULE
// EXCEPTION (precise le 2026-09-29) : le texte du seul motif qu'il pose lui-meme,
// `MOTEUR_INJOIGNABLE` plus bas, puisque le moteur ne repond pas quand il le pose.
const libellesMotifs = {};
const results = []; /* PROGRESS_PDF_START_v1 */ try { await this.helpers.httpRequest({ method:'POST', url:'http://host.docker.internal:8080/api/module-progress/start', body:JSON.stringify({mode:'pdf-fetch', total:toFetch.length, label:'pdf-fetch'}), headers:{'Content-Type':'application/json'}, timeout:3000 }); } catch(e) {}

// === BILAN_BIBLIO_FICHIER_v1 (2026-09-29) : LE BILAN DE LA BIBLIOTHEQUE DE REFERENCES EST RANGE
// DANS LE DOSSIER DU RUN par la route /api/zotero/pdf-bilan (POST), « en_cours » ici, puis les
// champs `_biblio_*` de chaque article a la fin du nœud. POURQUOI : la revue complete appelle ce
// nœud comme sous-workflow, et aucun de ses nœuds n'ecrit le corpus apres la recuperation des
// PDF ; le bilan par motif n'atteignait donc aucun ecran pour elle (refutation du tour 3). Le
// dossier d'une revue complete sert d'un run a l'autre : « en_cours » remplace le bilan du run
// precedent des maintenant, pour qu'un run arrete avant sa fin ne montre pas celui d'un autre.
async function rangerBilanBiblio(ctx, etat, articles) {
  try {
    await ctx.helpers.httpRequest({ method: 'POST',
      url: 'http://host.docker.internal:8080/api/zotero/pdf-bilan',
      body: JSON.stringify({ folder: outputFolder, etat: etat, articles: articles || [] }),
      headers: { 'Content-Type': 'application/json' }, json: true, timeout: 30000 });
  } catch (e) {
    // UN BILAN NON RANGE SE DIT dans le journal du nœud : l'ecran du run n'en montrera pas.
    console.log('  Bilan de la bibliotheque de references non range (' + etat + ') : ' + String((e && e.message) || e).substring(0, 160));
    console.log('        (en) Reference library summary not stored (' + etat + '): ' + String((e && e.message) || e).substring(0, 160));
  }
}
await rangerBilanBiblio(this, 'en_cours', []);

// LE MOTIF QUE PORTE UNE REPONSE DU MOTEUR, ou `null` si ce n'est pas une reponse du moteur
// (2026-09-23). Rend [clef, francais, anglais, detail technique]. Un corps texte est relu
// comme du JSON, parce qu'un statut d'erreur peut arriver sans avoir ete decode.
function motifDuMoteur(corps) {
  if (typeof corps === 'string') {
    try { corps = JSON.parse(corps); } catch (x) { return null; }
  }
  if (!corps || typeof corps !== 'object' || !corps.motif) return null;
  return [corps.motif, corps.motif_fr || null, corps.motif_en || null,
          corps.detail_technique || null];
}
// LE SEUL MOTIF QUE CE NŒUD POSE LUI-MEME : ce n'est pas la bibliotheque qui n'a pas repondu,
// c'est le moteur. Sa clef appartient a la meme liste fermee, cote moteur
// (zotero_client.MOTIFS) ; depuis le 2026-09-29, tests/test_biblio_reprise_du_29.py exige que
// sa clef ET ses deux textes egalent ceux du moteur (la garde d'avant ne comparait que la clef).
const MOTEUR_INJOIGNABLE = ['moteur_injoignable',
  "le moteur n'a pas répondu à la demande de recherche dans votre bibliothèque de références",
  'the engine did not answer the reference-library lookup request', null];

// LES MOTIFS QUE CE NOEUD POSE LUI-MEME DANS LA CASCADE (CASCADE_PDF_v1, 2026-10-13) : ceux qu'il
// constate sans reponse lisible d'un moteur. Leur liste fermee vit dans le relais
// (`proxy.MOTIFS_TELECHARGEMENT`), avec ceux que /download rend ; tests/test_chaine_pdf_cascade.py
// exige que chaque clef et ses deux textes y soient egaux. Les autres textes viennent des reponses.
const MOTIFS_DU_NOEUD = {
  relais_injoignable: ["le relais de téléchargement n'a pas répondu",
    'the download relay did not answer'],
  telechargement_sans_motif: ['le téléchargement a échoué sans motif rendu par le relais',
    'the download failed without a reason returned by the relay'],
  aucune_adresse_libre: ["aucune source en libre accès n'a donné d'adresse de PDF pour ce DOI",
    'no open-access source gave a PDF address for this DOI'],
  source_injoignable: ["une source en libre accès n'a pas répondu à la recherche de ce DOI",
    'an open-access source did not answer the lookup of this DOI'],
  source_cadence_limitee: ['une source en libre accès a demandé de ralentir (limite de cadence) : sa recherche a été abandonnée',
    'an open-access source asked to slow down (rate limit): its lookup was given up'],
  moteur_injoignable_editeur: ["le moteur n'a pas répondu à la demande faite à l'éditeur souscrit",
    'the engine did not answer the request to the subscribed publisher'],
  refus_editeur: ["l'éditeur souscrit n'a pas rendu le PDF ; sa raison l'accompagne",
    'the subscribed publisher did not return the PDF; its reason comes with it'],
  doi_absent: ["cette référence ne porte pas de DOI : aucune source n'a été interrogée",
    'this reference has no DOI: no source was queried'],
};

function motifDuNoeud(clef, detail) {
  const t = MOTIFS_DU_NOEUD[clef];
  return [clef, t[0], t[1], detail || null];
}

// Un essai rate : la source, et le motif [clef, francais, anglais, detail] qui le dit.
function essai(source, m) {
  return { source: source, motif: m[0], fr: m[1] || m[0], en: m[2] || m[0], detail: m[3] || null };
}

// Le statut HTTP d'une erreur du moteur de workflows (forme d'une erreur axios, ou champs a plat).
function statutDe(err) {
  const r = (err && err.response) || {};
  const s = Number(r.status || r.statusCode || (err && (err.statusCode || err.httpCode)) || 0);
  return Number.isFinite(s) ? s : 0;
}

// La recherche d'une source libre qui a leve est un essai rate, la limite de cadence dite a part.
// Un 404 n'en est pas un : c'est une reponse, ce DOI n'est pas connu de la source.
function noterLaRecherche(source, err, etat) {
  if (statutDe(err) === 404) return;
  const detail = String((err && err.message) || err).substring(0, 200);
  etat.essais.push(essai(source, statutDe(err) === 429 ? motifDuNoeud('source_cadence_limitee', detail)
    : motifDuNoeud('source_injoignable', detail)));
}

// Telecharge `url` par le relais vers `chemin`. Rend null si le PDF est ecrit, sinon le motif
// [clef, francais, anglais, detail] : celui que le relais rend, ou celui que ce noeud constate.
async function telechargerUnPdf(ctx, url, chemin) {
  let rep;
  try {
    rep = await ctx.helpers.httpRequest({
      method: 'POST',
      url: PROXY + '/download',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ url: url, save_to: chemin }),
      json: true,
      // LE CORPS D'UN REFUS EST DEMANDE : il porte le motif (page web, fichier vide, trop gros).
      ignoreHttpStatusErrors: true,
      timeout: DELAI_TELECHARGEMENT_MS
    });
  } catch (err) {
    const r = (err && err.response) || {};
    const m = motifDuMoteur(r.data !== undefined ? r.data : r.body);
    if (m) return m;
    return motifDuNoeud('relais_injoignable', String((err && err.message) || err).substring(0, 200));
  }
  if (rep && rep.success === true) return null;
  const m = motifDuMoteur(rep);
  if (m) return m;
  return motifDuNoeud('telechargement_sans_motif',
    rep && rep.error ? String(rep.error).substring(0, 200) : null);
}

// Essaie les adresses d'une source, dans l'ordre, sauf celles deja essayees pour cet article.
async function essayerLesAdresses(ctx, source, adresses, etat) {
  for (const url of adresses) {
    if (!url || etat.essayees.indexOf(url) >= 0) continue;
    etat.essayees.push(url);
    if (etat.premiere === null) etat.premiere = url;
    const echec = await telechargerUnPdf(ctx, url, etat.chemin);
    if (!echec) {
      etat.adresse = url;
      etat.provenance = source;
      return true;
    }
    etat.essais.push(essai(source, echec));
    stats.telechargements_refuses++;
  }
  return false;
}

// UN PDF DE L'EDITEUR SOUSCRIT (2026-10-13). Pas d'adresse web : la valeur etait une fausse
// adresse (« publisher:// ») qui partait dans la colonne des adresses du classeur d'export, comme
// celle de la bibliotheque de references avant le 2026-09-29 ; la source est dans `pdf_source`.
// LE LIBRE ACCES SUIT LA PROVENANCE (`libreSelonLaProvenance`, tour 4 du 2026-10-14 ; preuve E de la
// refutation du tour 3) : le PDF de l'abonnement n'est pas en libre acces ; celui d'une voie qui ne
// sert que le libre acces de son editeur l'est, et `oa_status` garde alors le statut libre
// qu'Unpaywall a dit, sinon il nomme la source, comme pour une source libre. Au tour 3, tout PDF de
// l'editeur etait marque hors du libre acces.
function pdfDeLEditeur(article, source) {
  if (libreSelonLaProvenance(source)) {
    article.is_oa = true;
    if (STATUTS_LIBRES.indexOf(article.oa_status) < 0) article.oa_status = source;
    return;
  }
  article.is_oa = false;
  article.oa_status = 'acces_editeur';
}

// LE REFUS DE L'EDITEUR SOUSCRIT, note comme un essai quand une demande est partie. Une reponse
// rendue sans demande (`demande_envoyee` faux, src/publisher_fetch.py, 2026-10-14) n'est pas un
// essai : elle n'est gardee que pour dire la cause d'un article sans aucun essai rate, et
// l'editeur qui n'est pas gere ne l'est meme pas. Une reponse sans motif (moteur d'une version
// anterieure) garde sa raison en detail.
function noterLeRefusDeLEditeur(edResp, etat) {
  const mEd = motifDuMoteur(edResp)
    || (edResp && edResp.raison ? motifDuNoeud('refus_editeur', String(edResp.raison).substring(0, 200))
      : motifDuNoeud('moteur_injoignable_editeur', null));
  if (mEd[0] === 'editeur_non_gere') return;
  if (edResp && edResp.demande_envoyee === false) {
    etat.sansDemande = essai('editeur', mEd);
    return;
  }
  etat.essais.push(essai('editeur', mEd));
}

// UNE CAUSE EST UNE CLEF ET SES DEUX TEXTES (2026-10-14, tour 3). Le relais et la route de
// l'editeur emploient quatre clefs communes aux textes differents (certificat_refuse, doi_absent,
// pas_un_pdf, trop_volumineux ; releve du 2026-10-14 sur proxy.MOTIFS_TELECHARGEMENT et
// publisher_fetch.MOTIFS) : comptees par clef seule, deux causes etaient publiees sous le texte du
// dernier article. Et ce texte remplacait, dans `libellesMotifs`, celui d'un motif de la
// bibliotheque de references de meme clef (doi_absent, dossier_hors_emplacements, meme releve sur
// zotero_client.MOTIFS), que les lignes de la bibliotheque lisent plus bas.
function compterLaCause(motif, fr, en) {
  const k = JSON.stringify([motif, fr, en]);
  const c = stats.motifs_pdf[k] = stats.motifs_pdf[k] || { motif: motif, fr: fr, en: en, n: 0 };
  c.n++;
}

// LES CHAMPS DE CAUSE QUE CE NOEUD POSE (2026-10-14) : retires de chaque article avant tout essai,
// exclu compris (voir l'en-tete). Sans ce retrait, un article servi dans ce run gardait la cause
// d'un run d'avant, et un article exclu etait compte « sans PDF, par cause ».
const CHAMPS_DE_CAUSE = ['_pdf_motif', '_pdf_motif_fr', '_pdf_motif_en', '_pdf_essais',
                         '_pdf_detail', '_editeur_raison'];
function sansCauseAncienne(a) {
  const copie = { ...a };
  for (const k of CHAMPS_DE_CAUSE) delete copie[k];
  return copie;
}

// LE LIBRE ACCES D'UN PDF DEJA LA, SELON SA PROVENANCE (2026-10-14) : vrai pour une source libre,
// faux pour la bibliotheque de references et l'editeur souscrit (vrai, depuis le tour 4, pour la
// voie d'un editeur qui ne sert que son libre acces), null pour une autre provenance
// (un PDF fourni a l'import : son regime n'est pas connu, la valeur portee est gardee). Ce noeud
// ecrit `pdf_source` avec 'zotero', 'unpaywall', 'core', 'europepmc', 'editeur:<editeur>', et
// 'import' quand cette branche n'en trouve pas ; le HEAD 780e20c ecrivait les memes six. Releve du
// 2026-10-14 (tour 3) dans le code de chaque noeud de workflows/ : un seul autre noeud l'ecrit,
// « Pass Through PDF » de ce workflow, qui recopie `pdf_source` et `is_oa` d'un PDF deja la sans
// regarder la provenance ; il ne sert qu'un appel portant `skip_pdf` vrai, que le module ne fait
// pas en mode de recuperation des PDF (« Prepare Articles », workflows/ultralab-module.json).
// Aucun fichier de src/ ni de app/src hors des cas de test ne nomme `pdf_source` (meme jour).
const SOURCES_LIBRES = ['unpaywall', 'core', 'europepmc'];
// La copie de `publisher_fetch.EDITEURS_DU_LIBRE_ACCES` (tour 4, 2026-10-14) : les editeurs dont la
// voie ne sert que leur libre acces. tests/test_chaine_pdf_cascade.py exige les deux listes egales.
const EDITEURS_DU_LIBRE_ACCES = ['springer'];
function libreSelonLaProvenance(source) {
  const s = String(source || '');
  if (SOURCES_LIBRES.indexOf(s) >= 0) return true;
  if (s.indexOf('editeur:') === 0) return EDITEURS_DU_LIBRE_ACCES.indexOf(s.slice('editeur:'.length)) >= 0;
  if (s === 'zotero') return false;
  return null;
}

// LES FAUSSES ADRESSES qu'ecrivaient des versions anterieures de ce noeud pour un PDF sans
// adresse web : « zotero://local » (jusqu'a 780e20c) et « publisher://<editeur> » (jusqu'a ce lot),
// relevees par git log -S sur ce workflow le 2026-10-14. Elles partaient dans les colonnes
// d'adresse du classeur.
function adresseWeb(url) {
  if (!url) return null;
  return /^(zotero|publisher):\/\//i.test(String(url)) ? null : url;
}

// SOURCE 1 : Unpaywall. Rend ESSAIS_UNPAYWALL_MAX adresses distinctes au plus, la meilleure
// d'abord. Pose sur l'article ce qu'Unpaywall dit de son acces libre.
async function adressesUnpaywall(ctx, doi, article, etat) {
  const adresses = [];
  const ajouter = function (u) {
    if (u && adresses.indexOf(u) < 0 && adresses.length < ESSAIS_UNPAYWALL_MAX) adresses.push(u);
  };
  try {
