// SOURCE 2 : CORE (sans cle). Le relais tient sa cadence publiee et son Retry-After.
async function adresseCore(ctx, doi, etat) {
  try {
    const coreUrl = 'https://api.core.ac.uk/v3/search/works?q=doi:' + encodeURIComponent(doi) + '&limit=1';
    const coreResp = await ctx.helpers.httpRequest({ method: 'GET', url: PROXY + '?url=' + encodeURIComponent(coreUrl) + '&_ultralab_module=pdf-fetch', timeout: DELAI_CORE_MS });
    if (coreResp && Array.isArray(coreResp.results) && coreResp.results.length > 0) {
      const work = coreResp.results[0];
      if (work.downloadUrl) return work.downloadUrl;
      if (work.sourceFulltextUrls && work.sourceFulltextUrls.length > 0) return work.sourceFulltextUrls[0];
    }
  } catch (err) {
    noterLaRecherche('core', err, etat);
  }
  return null;
}

// SOURCE 3 : Europe PMC (large couverture biomedicale).
async function adresseEuropePmc(ctx, doi, etat) {
  try {
    const epmcUrl = 'https://www.ebi.ac.uk/europepmc/webservices/rest/search?query=DOI:' + encodeURIComponent(doi) + '&resultType=core&format=json';
    const epmcResp = await ctx.helpers.httpRequest({ method: 'GET', url: PROXY + '?url=' + encodeURIComponent(epmcUrl) + '&_ultralab_module=pdf-fetch', timeout: 15000 });
    const result = epmcResp && epmcResp.resultList && epmcResp.resultList.result && epmcResp.resultList.result[0];
    if (result) {
      // Europe PMC fournit des fullTextUrlList avec type=Article + documentStyle=pdf
      const urls = (result.fullTextUrlList && result.fullTextUrlList.fullTextUrl) || [];
      for (const u of urls) {
        if (u.documentStyle === 'pdf' && (u.availability === 'Open access' || u.availability === 'Free')) return u.url;
      }
      // Repli : PMCID -> adresse directe du PDF
      if (result.pmcid) return 'https://europepmc.org/articles/' + result.pmcid + '?pdf=render';
    }
  } catch (err) {
    noterLaRecherche('europepmc', err, etat);
  }
  return null;
}

function sanitizeFilename(name) {
  return (name || 'article').substring(0, 80).replace(/[^a-zA-Z0-9_-]/g, '_').replace(/_+/g, '_');
