// La cle d'un article : son DOI sans espaces, en minuscules (un DOI ne distingue pas la casse).
function cleDuDoi(doi) {
  return String(doi || '').trim().toLowerCase();
}
function empreinteDuDoi(cle) {
  let h = 0x811c9dc5;
  for (let k = 0; k < cle.length; k++) {
    h ^= cle.charCodeAt(k);
    h = Math.imul(h, 0x01000193) >>> 0;
  }
  return ('0000000' + h.toString(16)).slice(-8);
}
function nomDeFichier(chemin) {
  const base = String(chemin || '').split(/[\\/]/).pop();
  return base.toLowerCase().endsWith('.pdf') ? base.slice(0, -4) : base;
}
