}
function nomDuPdf(article, doi) {
  const cle = cleDuDoi(doi);
  const base = (sanitizeFilename(article.title).substring(0, 60).replace(/_+$/, '') || 'article')
    + '_' + empreinteDuDoi(cle);
  let nom = base;
  for (let n = 2; nomsPris[nom.toLowerCase()] !== undefined && nomsPris[nom.toLowerCase()] !== cle; n++) {
    nom = base + '_' + n;
  }
  nomsPris[nom.toLowerCase()] = cle;
  return nom;
}

